import re, requests, subprocess, json, sys, time
from bs4 import BeautifulSoup
from urllib.parse import urljoin
BASE = 'http://the-agent-company.com:8929'
USER='root'
PASS='theagentcompany'

s = requests.Session()
s.headers.update({'User-Agent': 'cleanup/1.0'})

projects = set()
# Try public API first
try:
    page = 1
    while True:
        r = s.get(f'{BASE}/api/v4/projects', params={'per_page': 100, 'page': page, 'simple': 'true', 'order_by': 'last_activity_at', 'sort': 'desc'}, timeout=15)
        if r.status_code != 200:
            break
        data = r.json()
        if not data:
            break
        for p in data:
            # Accept only non-archived
            if p.get('archived'):
                continue
            projects.add(p['path_with_namespace'])
        page += 1
except Exception as e:
    pass

# Fallback: parse explore projects
try:
    page = 1
    while True:
        r = s.get(f'{BASE}/explore/projects', params={'page': page}, timeout=15)
        if r.status_code != 200:
            break
        soup = BeautifulSoup(r.text, 'html.parser')
        found = 0
        for a in soup.find_all('a', href=True):
            href = a['href']
            if re.match(r'^/[^/]+/[^/]+$', href):
                projects.add(href.strip('/'))
                found += 1
        if found == 0:
            break
        page += 1
except Exception as e:
    pass

projects = sorted(projects)
print('Found projects:', projects)

from urllib.parse import quote

def git_ls_remote_heads(url):
    out = subprocess.check_output(['git', 'ls-remote', '--heads', url], stderr=subprocess.STDOUT, text=True, timeout=60)
    branches = []
    for line in out.splitlines():
        parts = line.split('\t')
        if len(parts) == 2 and parts[1].startswith('refs/heads/'):
            branches.append(parts[1].split('/')[-1])
    return branches

def git_default_branch(url):
    try:
        out = subprocess.check_output(['git', 'ls-remote', '--symref', url, 'HEAD'], stderr=subprocess.STDOUT, text=True, timeout=30)
        for line in out.splitlines():
            if line.startswith('ref:') and '\tHEAD' in line:
                ref = line.split('\t')[0].split(':',1)[1].strip()
                return ref.split('/')[-1]
    except subprocess.CalledProcessError as e:
        pass
    return None

def git_delete_branch(url, branch):
    try:
        out = subprocess.check_output(['git', 'push', url, '--delete', branch], stderr=subprocess.STDOUT, text=True, timeout=60)
        return True, out
    except subprocess.CalledProcessError as e:
        return False, e.output

results = []
for path in projects:
    repo_url = f'{BASE}/{path}.git'
    # inject basic auth
    auth_url = f'http://{USER}:{PASS}@{BASE.split("//",1)[1]}/{path}.git'
    try:
        branches = git_ls_remote_heads(auth_url)
    except subprocess.CalledProcessError as e:
        results.append({'project': path, 'error': 'ls-remote failed', 'details': e.output})
        continue
    if not branches:
        results.append({'project': path, 'default': None, 'deleted': [], 'skipped': [], 'failed': [], 'note': 'no branches'})
        continue
    default = git_default_branch(auth_url)
    if not default:
        if 'main' in branches: default = 'main'
        elif 'master' in branches: default = 'master'
        else: default = branches[0]
    to_delete = [b for b in branches if b != default]
    deleted = []
    failed = []
    for b in to_delete:
        ok, out = git_delete_branch(auth_url, b)
        if ok:
            deleted.append(b)
        else:
            failed.append({'branch': b, 'error': out[:2000]})
    results.append({'project': path, 'default': default, 'deleted': deleted, 'failed': failed})

print(json.dumps(results, indent=2))
